# Main script for GalaxyDynamics
# DO NOT EDIT THIS FILE UNLESS YOU KNOW WHAT YOU ARE DOING.

# Imports
print("Importing Libraries")

import math
import sys

from PySide6.QtCore import Qt
from PySide6.QtWidgets import (
    QApplication,
    QWidget,
    QVBoxLayout,
    QLineEdit,
    QPushButton,
    QMessageBox,
    QFrame,
    QStackedWidget,
    QScrollArea,
    QLabel,
)

BG_COLOR       = "#050814"   # almost-black deep blue
SURFACE_COLOR  = "#0B1024"   # dark space blue
CARD_COLOR     = "#111735"   # blue-indigo
HOVER_COLOR    = "#17204A"   # stronger deep blue
BORDER_COLOR   = "#252B59"   # indigo-blue
ACCENT_BLUE    = "#3155D8"   # deep electric blue
ACCENT_INDIGO  = "#4A3FA3"   # dark indigo
ACCENT_PURPLE  = "#6A3FA0"   # deep purple
TEXT_COLOR     = "#E5E9FF"   # cool blue-white
SECONDARY_TEXT = "#7882A8"   # muted blue-gray

HeaderFont = "Space Grotesk"
SubHeaderFont = "Inter"
TechNumFont = "JetBrains Mono"

# --------------------------------------------------
# APPLICATION
# --------------------------------------------------

main = QApplication(sys.argv)


# --------------------------------------------------
# MAIN WINDOW
# --------------------------------------------------

window = QWidget()
window.showMaximized()

window.setStyleSheet(
    f"""
    QWidget {{
        background-color: {BG_COLOR};
        color: {TEXT_COLOR};
    }}
    """
)

# --------------------------------------------------
# HOMESCREEN
# --------------------------------------------------

Home = QWidget()
HomeLayout = QVBoxLayout(Home)

layout = QVBoxLayout(window)

# Header
header = QLabel("Galaxy Dynamics")
header.setStyleSheet(
    f"""
    color: {TEXT_COLOR};
    font-family: "{HeaderFont}";
    font-size: 32px;
    font-weight: bold;
    """
)

layout.addWidget(
    header,
    alignment=Qt.AlignmentFlag.AlignHCenter
)

Cal_Button = QPushButton("Calulators🛰️")
Set_Button = QPushButton("Settings⚙️")
VersionLabel = QLabel("v0.3 [beta]")

HomeLayout.addWidget(Cal_Button)
HomeLayout.addWidget(Set_Button)
HomeLayout.addWidget(VersionLabel)

Cal_Button.setFixedSize(550,300)

Cal_Button.setStyleSheet(
    f"""
    QPushButton {{
        background-color: {CARD_COLOR};
        color: {TEXT_COLOR};
        font-size: 50px;
        font-family: {HeaderFont};s
        border: 2px solid {BORDER_COLOR};
        border-radius: 16px;
    }}

    QPushButton:hover {{
        background-color: {HOVER_COLOR};
        border: 2px solid {ACCENT_BLUE};
    }}

    QPushButton:pressed {{
        background-color: {ACCENT_INDIGO};
    }}
    """
)

Cal_Button.font = HeaderFont
Cal_Button.clicked.connect(
    lambda: Stack.setCurrentWidget(Cal)
)

Set_Button.setFixedSize(550,300)

Set_Button.setStyleSheet(
    f"""
    QPushButton {{
        background-color: {CARD_COLOR};
        color: {TEXT_COLOR};
        font-size: 50px;
        font-family: {HeaderFont};
        border: 2px solid {BORDER_COLOR};
        border-radius: 16px;
    }}

    QPushButton:hover {{
        background-color: {HOVER_COLOR};
        border: 2px solid {ACCENT_INDIGO};
    }}

    QPushButton:pressed {{
        background-color: {ACCENT_PURPLE};
    }}
    """
)

Set_Button.clicked.connect(
    lambda: Stack.setCurrentWidget(Set)
)
VersionLabel.setStyleSheet(
    f"""
    QLabel {{
        color: {SECONDARY_TEXT};
        font-size: 32px;
        font-family: {SubHeaderFont};
    }}
    """
)

    

# --------------------------------------------------
# CALCULATORS PAGE
# --------------------------------------------------

Cal = QWidget()
CalLayout = QVBoxLayout(Cal)

# Scroll area
Scroll = QScrollArea()
Scroll.setWidgetResizable(True)

# Scrollable content
ScrollContent = QWidget()
ContentLayout = QVBoxLayout(ScrollContent)


Scroll.setWidget(ScrollContent)
CalLayout.addWidget(Scroll)

# The Calulators
#Delta v
Deltav_cal = QPushButton("DeltaV Calulator 🚀")
Deltav_cal.setFixedSize(700,400)
ContentLayout.addWidget(Deltav_cal)
Deltav_cal.setStyleSheet(
    f"""
    QPushButton {{
        background-color: {CARD_COLOR};
        color: {TEXT_COLOR};
        font-size: 50px;
        font-family: {HeaderFont};
        border: 2px solid {BORDER_COLOR};
        border-radius: 16px;
    }}

    QPushButton:hover {{
        background-color: {HOVER_COLOR};
        border: 2px solid {ACCENT_INDIGO};
    }}

    QPushButton:pressed {{
        background-color: {ACCENT_PURPLE};
    }}
    """
)

#Delta v
KeplerainOrbit_Cal = QPushButton("Keplerian Orbit Calulator 💫")
ContentLayout.addWidget(KeplerainOrbit_Cal)
KeplerainOrbit_Cal.setFixedSize(700,400)
KeplerainOrbit_Cal.setStyleSheet(
    f"""
    QPushButton {{
        background-color: {CARD_COLOR};
        color: {TEXT_COLOR};
        font-size: 50px;
        font-family: {HeaderFont};
        border: 2px solid {BORDER_COLOR};
        border-radius: 16px;
    }}

    QPushButton:hover {{
        background-color: {HOVER_COLOR};
        border: 2px solid {ACCENT_INDIGO};
    }}

    QPushButton:pressed {{
        background-color: {ACCENT_PURPLE};
    }}
    """
)


# --------------------------------------------------
# SETTINGS PAGE
# --------------------------------------------------

Set = QWidget()
SetLayout = QVBoxLayout(Set)


# --------------------------------------------------
# STACKED PAGE SYSTEM
# --------------------------------------------------

Stack = QStackedWidget()

Stack.addWidget(Home)
Stack.addWidget(Cal)
Stack.addWidget(Set)

# Start with Calculators for testing
Stack.setCurrentWidget(Home)

# Put the stack inside the main window
layout.addWidget(Stack)



# --------------------------------------------------
# OTHER
# --------------------------------------------------



# --------------------------------------------------
# SHOW APPLICATION
# --------------------------------------------------

window.show()

sys.exit(main.exec())